1381:     const p = this.player;
1382:     let tx, ty;
1383:     if (this.input.pointerActive) {
1384:       const z = this.camera.zoom || 1;
1385:       tx = Math.floor((this.camera.x + this.input.pointerX / z) / TILE);
1386:       ty = Math.floor((this.camera.y + this.input.pointerY / z) / TILE);
1387:     } else {
1388:       tx = Math.floor((p.x + Math.cos(p.angle) * 48) / TILE);
1389:       ty = Math.floor((p.y + Math.sin(p.angle) * 48) / TILE);
1390:     }
1391:     const d = dist(p.x, p.y, tx * TILE + 16, ty * TILE + 16);
1392:     let result = { type, tx, ty, valid: false, reason: '', portal: null };
1393:     if (d > TILE * 5) { result.reason = 'Longe demais'; return result; }
1394:     if (def.target === 'portal' || def.target === 'barricade') {
1395:       // encontra portal próximo
1396:       let best = null, bd = TILE * 2.2;
1397:       for (const dr of this.world.doors.values()) {
1398:         const dd = dist(tx * TILE + 16, ty * TILE + 16, dr.x * TILE + 16, dr.y * TILE + 16);
1399:         if (dd < bd) { bd = dd; best = { kind: 'door', ref: dr, x: dr.x, y: dr.y }; }
1400:       }
1401:       for (const w of this.world.windows.values()) {
1402:         if (w.broken) continue;
1403:         const dd = dist(tx * TILE + 16, ty * TILE + 16, w.x * TILE + 16, w.y * TILE + 16);
1404:         if (dd < bd) { bd = dd; best = { kind: 'window', ref: w, x: w.x, y: w.y }; }
1405:       }
1406:       if (!best) { result.reason = 'Aponte para uma porta ou janela'; return result; }
1407:       const existing = this.world.portalStructures.get(best.x + ',' + best.y);
1408:       if (type === 'barricada' && existing) { result.reason = 'Já existe uma barricada'; return result; }
1409:       if (type === 'reforco_metal' && (!existing || existing.type !== 'barricada')) { result.reason = 'Reforço exige uma barricada'; return result; }
1410:       result.tx = best.x; result.ty = best.y; result.portal = best; result.valid = true;
1411:       result.cost = def.cost;
1412:       return result;
1413:     }
1414:     if (!this.world.inBounds(tx, ty)) { result.reason = 'Fora dos limites'; return result; }
1415:     const t = this.world.tile(tx, ty);
1416:     if (t === T.WATER) { result.reason = 'Não é possível construir na água'; return result; }
1417:     if ([T.WALL, T.DOOR, T.WINDOW].includes(t)) { result.reason = 'Local ocupado'; return result; }
1418:     if (this.world.containerAtTile(tx, ty)) { result.reason = 'Há um móvel aqui'; return result; }
1419:     if (this.world.structureAt(tx, ty)) { result.reason = 'Já há uma construção aqui'; return result; }
1420:     if (this.world.trees.some(tr => Math.floor(tr.x / TILE) === tx && Math.floor(tr.y / TILE) === ty)) { result.reason = 'Uma árvore bloqueia o local'; return result; }
1421:     if (this.world.beds.some(b => b.x === tx && b.y === ty)) { result.reason = 'Há uma cama aqui'; return result; }
1422:     if (this.world.vehicles.some(v => !v.occupied && Math.floor(v.x / TILE) === tx && Math.floor(v.y / TILE) === ty)) { result.reason = 'Há um veículo aqui'; return result; }
