/* ==========================================================================
   ÚLTIMO ABRIGO — interface de sobrevivência
   Estética: apocalipse rural, metal enferrujado, papel e luz de fogueira.
   ========================================================================== */

:root {
  --ink: #eff0df;
  --ink-soft: #c8c8b3;
  --muted: #858b79;
  --bg: #070a08;
  --bg-2: #0c100d;
  --panel: rgba(18, 23, 17, 0.94);
  --panel-2: rgba(25, 31, 23, 0.92);
  --panel-solid: #141a13;
  --line: rgba(188, 195, 160, 0.16);
  --line-strong: rgba(205, 199, 155, 0.34);
  --amber: #e0b95f;
  --amber-2: #f3d68a;
  --amber-dim: #8f7436;
  --green: #9cbb72;
  --green-deep: #557545;
  --danger: #d05f54;
  --danger-2: #ee9186;
  --blue: #78b8d6;
  --purple: #b595cb;
  --shadow: 0 22px 70px rgba(0, 0, 0, 0.62);
  --radius: 12px;
  --radius-lg: 18px;
  --display: "Palatino Linotype", "Book Antiqua", Palatino, Georgia, serif;
  --sans: "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --mono: "SFMono-Regular", Consolas, "Liberation Mono", monospace;
  --safe: env(safe-area-inset-bottom, 0px);
}

* { box-sizing: border-box; }
html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--sans);
  font-size: 15px;
  line-height: 1.45;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}
body { overscroll-behavior: none; touch-action: none; }
button, input, select, textarea { font: inherit; color: inherit; }
button { cursor: pointer; border: 0; background: none; }
button:focus-visible, input:focus-visible, select:focus-visible { outline: 2px solid var(--amber); outline-offset: 2px; }
::selection { background: rgba(224, 185, 95, 0.28); color: #fff; }
::-webkit-scrollbar { width: 9px; height: 9px; }
::-webkit-scrollbar-track { background: rgba(0, 0, 0, 0.22); }
::-webkit-scrollbar-thumb { background: #3f4837; border-radius: 20px; border: 2px solid transparent; background-clip: padding-box; }
::-webkit-scrollbar-thumb:hover { background: #5b664d; background-clip: padding-box; border: 2px solid transparent; }

.hidden { display: none !important; }
.muted { color: var(--muted); }
.danger { color: var(--danger-2) !important; }
.warn { color: var(--amber) !important; }
kbd {
  display: inline-block;
  min-width: 20px;
  padding: 1px 6px;
  border: 1px solid rgba(222, 219, 188, 0.28);
  border-bottom-width: 2px;
  border-radius: 4px;
  background: rgba(255, 255, 255, 0.055);
  font-family: var(--mono);
  font-size: 0.72em;
  font-weight: 600;
  color: #ecebdc;
  text-align: center;
  box-shadow: inset 0 1px rgba(255, 255, 255, 0.08);
}

#app { position: fixed; inset: 0; overflow: hidden; }
#gameCanvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; background: #0a0d0a; }

/* ==========================================================================
   TELAS E MENU
   ========================================================================== */
.screen {
  position: fixed;
  inset: 0;
  z-index: 40;
  overflow: hidden;
  background: radial-gradient(circle at 62% 40%, rgba(65, 67, 44, 0.35), transparent 55%), linear-gradient(120deg, #0b0f0b 0%, #11150f 48%, #080a07 100%);
}
.screen::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background-image: repeating-linear-gradient(0deg, rgba(255, 255, 255, 0.016) 0 1px, transparent 1px 3px);
  mix-blend-mode: overlay;
}

.menu-screen { background: #090c08; }
#menuCanvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }
.menu-vignette {
  position: absolute; inset: 0; pointer-events: none;
  background:
    linear-gradient(90deg, rgba(5, 7, 5, 0.93) 0%, rgba(5, 7, 5, 0.76) 34%, rgba(5, 7, 5, 0.17) 63%, rgba(5, 7, 5, 0.45) 100%),
    radial-gradient(ellipse at 66% 45%, transparent 20%, rgba(0, 0, 0, 0.58) 100%),
    linear-gradient(0deg, rgba(4, 6, 4, 0.94), transparent 27%);
}
.menu-content {
  position: relative;
  z-index: 2;
  display: flex;
  flex-direction: column;
  justify-content: center;
  height: 100%;
  max-width: 760px;
  padding: 50px clamp(28px, 7vw, 110px) 42px;
}
.brand { animation: rise 0.9s cubic-bezier(.18,.78,.3,1) both; }
.brand-kicker {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.36em;
  color: var(--amber);
  text-transform: uppercase;
  margin-bottom: 14px;
  display: flex;
  align-items: center;
  gap: 12px;
}
.brand-kicker::before { content: ""; width: 32px; height: 1px; background: var(--amber-dim); }
.brand h1 {
  margin: 0;
  font-family: var(--display);
  font-size: clamp(58px, 9.2vw, 126px);
  line-height: 0.8;
  font-weight: 700;
  letter-spacing: -0.055em;
  color: #efeddb;
  text-shadow: 0 2px 0 #1d2118, 0 12px 40px rgba(0, 0, 0, 0.6);
}
.brand h1 span {
  display: block;
  color: transparent;
  -webkit-text-stroke: 1px rgba(224, 185, 95, 0.76);
  text-shadow: 0 0 34px rgba(224, 185, 95, 0.12);
  letter-spacing: 0.05em;
  margin-left: 2px;
}
.brand-rule { width: 84px; height: 2px; margin: 26px 0 16px; background: linear-gradient(90deg, var(--amber), transparent); }
.tagline { margin: 0; color: #b4b5a3; font-size: 15px; letter-spacing: 0.03em; font-style: italic; }

.menu-actions {
  width: min(458px, 100%);
  margin-top: 44px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  animation: rise 1s 0.12s cubic-bezier(.18,.78,.3,1) both;
}
.menu-btn {
  position: relative;
  display: grid;
  grid-template-columns: 1fr auto;
  grid-template-rows: auto auto;
  column-gap: 14px;
  text-align: left;
  padding: 15px 17px 14px 20px;
  border: 1px solid rgba(191, 196, 165, 0.14);
  border-left: 3px solid rgba(191, 196, 165, 0.18);
  border-radius: 8px;
  background: linear-gradient(100deg, rgba(29, 35, 25, 0.84), rgba(16, 20, 15, 0.6));
  backdrop-filter: blur(7px);
  transition: transform 0.18s, border-color 0.18s, background 0.18s;
  overflow: hidden;
}
.menu-btn::after {
  content: "";
  position: absolute; inset: 0;
  background: linear-gradient(90deg, rgba(224, 185, 95, 0.09), transparent 55%);
  opacity: 0; transition: opacity 0.2s;
}
.menu-btn:hover { transform: translateX(5px); border-color: rgba(224, 185, 95, 0.4); border-left-color: var(--amber); background: linear-gradient(100deg, rgba(40, 44, 29, 0.92), rgba(20, 24, 16, 0.7)); }
.menu-btn:hover::after { opacity: 1; }
.menu-btn.primary { border-left-color: var(--amber); background: linear-gradient(100deg, rgba(49, 45, 26, 0.9), rgba(21, 24, 16, 0.7)); }
.menu-btn.ghost { background: rgba(13, 17, 12, 0.52); }
.mb-main { grid-column: 1; font-family: var(--display); font-size: 20px; font-weight: 700; letter-spacing: 0.01em; color: #f0eddc; }
.mb-sub { grid-column: 1; font-size: 11.5px; color: #929785; letter-spacing: 0.02em; }
.mb-arrow { grid-column: 2; grid-row: 1 / 3; align-self: center; color: var(--amber); font-size: 20px; transition: transform 0.18s; }
.menu-btn:hover .mb-arrow { transform: translateX(5px); }
.menu-btn.primary .mb-main { color: var(--amber-2); }

.menu-footer {
  display: flex; justify-content: space-between; gap: 16px; align-items: center;
  margin-top: auto; padding-top: 44px;
  font-size: 9.5px; letter-spacing: 0.16em; text-transform: uppercase; color: #676d5f;
  max-width: 560px;
}
#menuTip { text-transform: none; letter-spacing: 0.02em; color: #8c917f; font-style: italic; text-align: right; }
.menu-side {
  position: absolute; z-index: 2; right: clamp(24px, 5vw, 76px); bottom: clamp(28px, 7vh, 70px);
  display: flex; flex-direction: column; align-items: flex-end; gap: 18px;
  animation: rise 1.2s 0.28s cubic-bezier(.18,.78,.3,1) both;
}
.menu-side-card {
  min-width: 218px;
  border: 1px solid rgba(194, 190, 157, 0.15);
  background: rgba(10, 14, 10, 0.62);
  backdrop-filter: blur(10px);
  padding: 15px 17px;
  border-radius: 6px;
}
.msc-label { font-size: 8.5px; letter-spacing: 0.28em; color: var(--amber-dim); margin-bottom: 9px; }
.msc-row { display: flex; justify-content: space-between; gap: 28px; padding: 5px 0; border-bottom: 1px solid rgba(255,255,255,0.045); font-size: 11px; color: #898f7d; }
.msc-row:last-child { border: 0; }
.msc-row strong { color: #d8d8c5; font-weight: 600; }
.menu-side-quote { font-family: var(--display); font-size: 14px; color: #a7a68f; font-style: italic; text-align: right; line-height: 1.55; text-shadow: 0 2px 12px #000; }

@keyframes rise { from { opacity: 0; transform: translateY(18px); } to { opacity: 1; transform: none; } }
@keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
@keyframes panelIn { from { opacity: 0; transform: translateY(14px) scale(0.985); } to { opacity: 1; transform: none; } }
@keyframes pulseGlow { 0%,100% { box-shadow: 0 0 0 0 rgba(224,185,95,0); } 50% { box-shadow: 0 0 28px 2px rgba(224,185,95,0.15); } }

/* ==========================================================================
   PAINÉIS GERAIS
   ========================================================================== */
.screen-panel {
  position: relative;
  z-index: 2;
  width: min(1120px, calc(100vw - 40px));
  max-height: calc(100vh - 46px);
  margin: 23px auto;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  border: 1px solid var(--line-strong);
  border-radius: var(--radius-lg);
  background:
    linear-gradient(160deg, rgba(33, 39, 28, 0.97), rgba(13, 17, 12, 0.985)),
    repeating-linear-gradient(90deg, rgba(255,255,255,0.015) 0 1px, transparent 1px 9px);
  box-shadow: var(--shadow), inset 0 1px rgba(255, 255, 255, 0.05);
  animation: panelIn 0.35s cubic-bezier(.18,.78,.3,1) both;
}
.screen-panel::before {
  content: ""; position: absolute; inset: 0; pointer-events: none;
  background: radial-gradient(circle at 90% 0%, rgba(224,185,95,0.08), transparent 38%);
}
.panel-header {
  display: flex; align-items: center; gap: 18px;
  padding: 19px 25px 17px;
  border-bottom: 1px solid var(--line);
  background: rgba(4, 7, 4, 0.24);
  flex: 0 0 auto;
}
.panel-title { min-width: 0; }
.panel-title .kicker { display: block; font-size: 8.5px; letter-spacing: 0.28em; text-transform: uppercase; color: var(--amber-dim); font-weight: 700; margin-bottom: 2px; }
.panel-title h2 { margin: 0; font-family: var(--display); font-size: clamp(24px, 2.5vw, 34px); line-height: 1; font-weight: 700; color: #efeddb; letter-spacing: -0.01em; }
.panel-spacer { flex: 1; }
.btn-ghost { padding: 8px 10px; border-radius: 6px; color: #b4b7a5; font-size: 12px; transition: background 0.16s, color 0.16s; }
.btn-ghost:hover { background: rgba(255,255,255,0.06); color: #fff; }
.btn-close {
  width: 36px; height: 36px; margin-left: auto; border-radius: 8px;
  display: flex; align-items: center; justify-content: center;
  border: 1px solid var(--line); background: rgba(255,255,255,0.025);
  color: #b8baa8; font-size: 17px; transition: all 0.16s;
}
.btn-close:hover { background: rgba(208, 95, 84, 0.16); border-color: rgba(208,95,84,0.45); color: #fff; }

.btn-primary, .btn-secondary {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  padding: 11px 20px;
  border-radius: 7px;
  font-weight: 700;
  font-size: 12.5px;
  letter-spacing: 0.045em;
  text-transform: uppercase;
  transition: transform 0.16s, filter 0.16s, background 0.16s, border-color 0.16s;
}
.btn-primary {
  border: 1px solid #b89347;
  color: #1b190f;
  background: linear-gradient(180deg, #f0cc78, #c49b49);
  box-shadow: inset 0 1px rgba(255,255,255,0.35), 0 8px 22px rgba(0,0,0,0.28);
}
.btn-primary:hover { filter: brightness(1.08); transform: translateY(-1px); }
.btn-primary:active { transform: translateY(0); filter: brightness(0.96); }
.btn-primary:disabled { opacity: 0.36; cursor: not-allowed; transform: none; filter: grayscale(0.6); }
.btn-primary.big, .btn-secondary.big { padding: 14px 30px; font-size: 13.5px; }
.btn-secondary {
  border: 1px solid rgba(197, 197, 163, 0.24);
  background: rgba(255, 255, 255, 0.045);
  color: #dedfcd;
}
.btn-secondary:hover { background: rgba(255,255,255,0.085); border-color: rgba(224,185,95,0.38); }
.btn-secondary.small { padding: 6px 10px; font-size: 10.5px; letter-spacing: 0.02em; text-transform: none; }
.btn-secondary:disabled { opacity: 0.35; cursor: not-allowed; }

.field { display: flex; flex-direction: column; gap: 7px; }
.field > span, .field-label { font-size: 9.5px; font-weight: 700; letter-spacing: 0.19em; text-transform: uppercase; color: #929783; }
.field input, .field select {
  width: 100%;
  padding: 11px 13px;
  border: 1px solid rgba(195, 197, 164, 0.2);
  border-radius: 6px;
  background: rgba(4, 7, 4, 0.4);
  color: #f0eedb;
  transition: border-color 0.16s, background 0.16s;
}
.field input::placeholder { color: #5f6658; }
.field input:focus, .field select:focus { border-color: rgba(224,185,95,0.58); background: rgba(4,7,4,0.65); outline: none; }
.field select { appearance: none; background-image: linear-gradient(45deg, transparent 50%, #9b9e8a 50%), linear-gradient(135deg, #9b9e8a 50%, transparent 50%); background-position: calc(100% - 16px) 50%, calc(100% - 11px) 50%; background-size: 5px 5px, 5px 5px; background-repeat: no-repeat; }
.field select option { background: #151a13; }
.form-error { min-height: 18px; margin: 2px 0 0; color: var(--danger-2); font-size: 11.5px; }

/* ==========================================================================
   CRIAÇÃO DE PERSONAGEM
   ========================================================================== */
.char-panel { width: min(1180px, calc(100vw - 40px)); height: min(880px, calc(100vh - 46px)); }
.char-body { padding: 24px 28px 20px; overflow: auto; display: flex; flex-direction: column; flex: 1; }
.char-top { display: grid; grid-template-columns: minmax(240px, 0.92fr) 1.08fr; gap: 26px; margin-bottom: 26px; }
.difficulty-wrap { display: flex; flex-direction: column; gap: 7px; }
.difficulty-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.diff-card {
  text-align: left; padding: 11px 13px; border: 1px solid var(--line);
  border-radius: 7px; background: rgba(255,255,255,0.025); transition: all 0.16s;
}
.diff-card strong { display: block; font-size: 12.5px; color: #dedfcd; margin-bottom: 2px; }
.diff-card small { display: block; font-size: 10px; color: #858b79; line-height: 1.35; }
.diff-card:hover { border-color: rgba(224,185,95,0.3); }
.diff-card.active { border-color: var(--amber); background: rgba(224,185,95,0.105); box-shadow: inset 0 0 22px rgba(224,185,95,0.06); }
.diff-card.active strong { color: var(--amber-2); }
.background-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; margin-top: 8px; }
.bg-card {
  position: relative; text-align: left; min-height: 126px;
  padding: 14px 14px 13px;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: linear-gradient(155deg, rgba(255,255,255,0.032), rgba(255,255,255,0.012));
  transition: all 0.17s;
  overflow: hidden;
}
.bg-card::before { content: ""; position: absolute; inset: auto 0 0; height: 2px; background: var(--amber); transform: scaleX(0); transform-origin: left; transition: transform 0.2s; }
.bg-card:hover { transform: translateY(-2px); border-color: rgba(224,185,95,0.33); background: rgba(255,255,255,0.05); }
.bg-card.active { border-color: var(--amber); background: linear-gradient(155deg, rgba(224,185,95,0.14), rgba(255,255,255,0.02)); }
.bg-card.active::before { transform: scaleX(1); }
.bg-icon { font-size: 23px; display: block; margin-bottom: 5px; }
.bg-card strong { display: block; font-family: var(--display); font-size: 16px; color: #e9e7d5; }
.bg-card p { margin: 4px 0 0; color: #929986; font-size: 10.5px; line-height: 1.42; }
.bg-skills { display: flex; flex-wrap: wrap; gap: 4px; margin-top: 9px; }
.bg-skills span { font-size: 8.5px; letter-spacing: 0.06em; color: var(--amber); border: 1px solid rgba(224,185,95,0.24); background: rgba(224,185,95,0.06); border-radius: 20px; padding: 2px 6px; }
.char-footer { display: flex; justify-content: space-between; align-items: center; gap: 22px; margin-top: auto; padding-top: 24px; }
.char-summary {
  flex: 1; border-left: 2px solid rgba(224,185,95,0.42);
  padding: 10px 16px; color: #b6b9a5; font-size: 12px; line-height: 1.6;
  background: linear-gradient(90deg, rgba(224,185,95,0.06), transparent 80%);
}
.char-summary strong { color: var(--amber-2); }

/* ==========================================================================
   CARREGAMENTO
   ========================================================================== */
.loading-screen { display: flex; align-items: center; justify-content: center; background: #080b08; }
.loading-content { width: min(500px, calc(100vw - 44px)); text-align: center; }
.loading-mark { font-size: 58px; color: var(--amber); filter: drop-shadow(0 0 26px rgba(224,185,95,0.3)); animation: pulseGlow 2.4s infinite; border-radius: 50%; width: 96px; height: 96px; line-height: 96px; margin: 0 auto 22px; }
.loading-content h2 { font-family: var(--display); font-size: 29px; margin: 0 0 6px; }
.loading-content p { color: #969b87; font-size: 12.5px; margin: 0 0 26px; }
.loading-bar { height: 4px; width: 100%; background: rgba(255,255,255,0.08); overflow: hidden; border-radius: 4px; }
.loading-bar i { display: block; height: 100%; width: 4%; background: linear-gradient(90deg, #76602c, var(--amber-2)); transition: width 0.3s ease; box-shadow: 0 0 12px rgba(224,185,95,0.4); }
.loading-tip { margin-top: 36px !important; font-size: 10.5px !important; color: #626957 !important; font-style: italic; letter-spacing: 0.02em; }

/* ==========================================================================
   MULTIJOGADOR
   ========================================================================== */
.mp-panel { width: min(1000px, calc(100vw - 40px)); }
.mp-body { display: grid; grid-template-columns: 1fr 360px; gap: 28px; padding: 28px; overflow: auto; }
.mp-info { border-right: 1px solid var(--line); padding-right: 28px; }
.mp-badge { display: inline-block; font-size: 9px; letter-spacing: 0.2em; color: #1b190f; background: var(--amber); padding: 4px 9px; border-radius: 4px; font-weight: 800; margin-bottom: 14px; }
.mp-info p { font-size: 13px; color: #b4b7a4; line-height: 1.65; }
