.mp-note { border: 1px solid rgba(208,95,84,0.24); border-left: 3px solid var(--danger); background: rgba(208,95,84,0.07); padding: 11px 13px; border-radius: 5px; font-size: 10.5px !important; color: #d5a19a !important; }
