.lobby-actions { grid-column: 1 / -1; border-top: 1px solid var(--line); padding: 15px 24px; display: flex; align-items: center; justify-content: space-between; gap: 18px; }
.lobby-actions p { margin: 0; font-size: 11.5px; }
.lobby-chat { grid-column: 1 / -1; border-top: 1px solid var(--line); padding: 13px 18px; background: rgba(0,0,0,0.18); }
