}
.intro-panel { position: relative; z-index: 2; width: min(700px, calc(100vw - 44px)); max-height: calc(100vh - 50px); overflow: auto; padding: 36px 40px; border-left: 2px solid var(--amber-dim); background: linear-gradient(100deg, rgba(16,21,15,0.82), rgba(10,13,10,0.42)); animation: rise 0.8s both; }
