.ig-title { font-size: 8.5px; letter-spacing: 0.25em; color: var(--amber-dim); margin-bottom: 10px; }
.ig-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 9px; color: #c9cab7; font-size: 12px; }
.intro-actions { display: flex; align-items: center; gap: 20px; flex-wrap: wrap; }
.intro-hint { font-size: 10px; color: #858b78; }

/* ==========================================================================
   HUD
   ========================================================================== */
#hud { position: fixed; inset: 0; z-index: 12; pointer-events: none; font-size: 12px; }
