.v-bar { flex: 1; height: 7px; border-radius: 6px; background: rgba(255,255,255,0.075); overflow: hidden; box-shadow: inset 0 1px 2px rgba(0,0,0,0.4); }
.v-bar i { display: block; height: 100%; width: 100%; border-radius: inherit; transition: width 0.35s ease, background 0.3s; background: #7fae62; }
.vital[data-v="health"] .v-bar i { background: linear-gradient(90deg, #93443d, #d56a5e); }
.vital[data-v="hunger"] .v-bar i { background: linear-gradient(90deg, #92762e, #d7aa54); }
.vital[data-v="thirst"] .v-bar i { background: linear-gradient(90deg, #346a86, #6fb6d3); }
.vital[data-v="stamina"] .v-bar i { background: linear-gradient(90deg, #6b7733, #b6ca6c); }
.vital[data-v="sleep"] .v-bar i { background: linear-gradient(90deg, #584579, #9b7fc0); }
.vital[data-v="hygiene"] .v-bar i { background: linear-gradient(90deg, #3f7069, #74b8ad); }
.v-val { width: 31px; text-align: right; font-family: var(--mono); font-size: 9px; color: #c4c7b3; }
.vital.low .v-bar i { background: linear-gradient(90deg, #a33c32, #e47868) !important; animation: blinkBar 0.9s infinite; }
.vital.low .v-val { color: #ef9b90; }
@keyframes blinkBar { 50% { opacity: 0.45; } }
.status-row { display: flex; flex-wrap: wrap; gap: 3px; margin-top: 2px; min-height: 0; }
.status-chip { font-size: 8px; padding: 1px 5px; border-radius: 3px; border: 1px solid; letter-spacing: 0.03em; }
.status-chip.bad { color: #eda498; border-color: rgba(208,95,84,0.3); background: rgba(208,95,84,0.1); }
.status-chip.warn { color: #dfc27a; border-color: rgba(224,185,95,0.26); background: rgba(224,185,95,0.08); }
.status-chip.info { color: #9cc7d9; border-color: rgba(120,184,214,0.24); background: rgba(120,184,214,0.08); }
.status-chip.good { color: #aecb8c; border-color: rgba(156,187,114,0.24); background: rgba(156,187,114,0.08); }

.hud-bottom-center { position: absolute; left: 50%; bottom: calc(16px + var(--safe)); transform: translateX(-50%); display: flex; flex-direction: column; align-items: center; gap: 8px; width: min(660px, calc(100vw - 40px)); }
.hotbar-wrap { display: flex; align-items: stretch; gap: 8px; }
.equipped-card {
  min-width: 116px; max-width: 150px; padding: 7px 11px;
  border: 1px solid rgba(201,197,163,0.22); border-radius: 7px;
  background: rgba(10,14,10,0.8); backdrop-filter: blur(8px);
  display: flex; flex-direction: column; justify-content: center; text-align: left;
}
.eq-label { font-size: 7.5px; letter-spacing: 0.2em; color: var(--amber-dim); }
#equippedName { font-family: var(--display); font-size: 14px; color: #e9e7d5; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.hotbar { display: flex; gap: 6px; }
.hot-slot {
  position: relative; width: 52px; height: 52px;
  border: 1px solid rgba(201,197,163,0.22); border-radius: 7px;
  background: rgba(10,14,10,0.82); backdrop-filter: blur(8px);
  display: flex; align-items: center; justify-content: center;
  font-size: 20px; transition: all 0.14s;
}
.hot-slot:hover { border-color: rgba(224,185,95,0.48); background: rgba(29,32,21,0.94); transform: translateY(-2px); }
.hot-slot.empty { opacity: 0.4; }
.hot-slot .hq { position: absolute; right: 4px; bottom: 2px; font-family: var(--mono); font-size: 9px; color: #d9dac9; text-shadow: 0 1px 2px #000; }
.hot-slot .hk { position: absolute; left: 4px; top: 2px; font-family: var(--mono); font-size: 7.5px; color: #8d927e; }
.interact-prompt {
  display: flex; align-items: center; gap: 8px; padding: 7px 13px;
  border: 1px solid rgba(224,185,95,0.4); border-radius: 6px;
  background: rgba(13,17,11,0.88); backdrop-filter: blur(7px);
  color: #e7e4d1; font-size: 11.5px; box-shadow: 0 6px 22px rgba(0,0,0,0.3);
  animation: fadeIn 0.15s both;
}
.interact-prompt kbd { background: var(--amber); color: #1b180e; border-color: #f0d68b; }
.ip-icon { font-size: 14px; }
.hint-bar { display: flex; flex-wrap: wrap; justify-content: center; gap: 4px 12px; padding: 3px 8px 1px; color: rgba(214,216,198,0.66); font-size: 9px; text-shadow: 0 1px 3px #000; }
.hint-bar kbd { font-size: 7.5px; border-color: rgba(255,255,255,0.18); background: rgba(0,0,0,0.34); }

.hud-right { position: absolute; right: 18px; top: 300px; width: 268px; display: flex; flex-direction: column; gap: 10px; }
.objectives-card { border: 1px solid rgba(200,196,162,0.18); border-radius: 8px; background: rgba(10,14,10,0.76); backdrop-filter: blur(8px); overflow: hidden; }
.objectives-card header { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 8px 10px 7px; border-bottom: 1px solid rgba(255,255,255,0.06); font-size: 9px; letter-spacing: 0.12em; color: #b6b8a3; text-transform: uppercase; }
.objectives-card header button { color: var(--amber); font-size: 15px; line-height: 1; padding: 0 3px; }
#objList { list-style: none; margin: 0; padding: 5px 0; max-height: 208px; overflow: auto; }
#objList li { display: flex; gap: 7px; align-items: flex-start; padding: 5px 10px; font-size: 10.5px; color: #c5c7b4; }
#objList li .oi { font-size: 11px; width: 15px; text-align: center; flex: 0 0 auto; }
#objList li.done { color: #757c6b; text-decoration: line-through; opacity: 0.65; }
#objList li.done .oi { filter: grayscale(1); }
.objectives-card.collapsed #objList { display: none; }

.toasts { display: flex; flex-direction: column; gap: 6px; max-width: 100%; }
.toast {
  display: flex; align-items: flex-start; gap: 8px; padding: 7px 10px;
  border-radius: 5px; border: 1px solid var(--line);
  border-left: 3px solid #8c947c;
  background: rgba(10,14,10,0.89); backdrop-filter: blur(7px);
  color: #d6d8c5; font-size: 10.5px; line-height: 1.35;
  box-shadow: 0 6px 20px rgba(0,0,0,0.28);
  animation: toastIn 0.25s cubic-bezier(.2,.9,.3,1) both;
  transition: opacity 0.35s, transform 0.35s;
}
.toast.out { opacity: 0; transform: translateX(12px); }
.toast .t-icon { font-size: 13px; flex: 0 0 auto; line-height: 1.2; }
.toast.good { border-left-color: var(--green); }
.toast.warn { border-left-color: var(--amber); }
.toast.danger { border-left-color: var(--danger); }
.toast.skill, .toast.level { border-left-color: var(--purple); }
.toast.day { border-left-color: var(--amber-2); }
.toast.mp { border-left-color: #6cd7c4; }
@keyframes toastIn { from { opacity: 0; transform: translateX(14px); } }

.event-banner {
  position: absolute; top: 106px; left: 50%; transform: translateX(-50%);
  display: flex; align-items: center; gap: 13px;
  width: min(470px, calc(100vw - 40px));
  padding: 11px 16px;
  border: 1px solid rgba(208,95,84,0.34);
  border-left: 3px solid var(--danger);
  border-radius: 6px;
  background: linear-gradient(100deg, rgba(41,20,16,0.94), rgba(15,15,11,0.86));
  box-shadow: 0 12px 40px rgba(0,0,0,0.4);
  backdrop-filter: blur(9px);
  animation: eventIn 0.4s cubic-bezier(.2,.9,.3,1) both;
}
.event-banner .ev-icon { font-size: 27px; }
.event-banner strong { display: block; font-family: var(--display); font-size: 17px; color: #f2decf; }
.event-banner p { margin: 1px 0 0; font-size: 10.5px; color: #c3a99f; }
@keyframes eventIn { from { opacity: 0; transform: translate(-50%, -12px); } }
.day-banner {
  position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%);
  display: flex; align-items: center; gap: 15px;
  padding: 19px 27px;
  border: 1px solid rgba(224,185,95,0.34);
  background: rgba(10,14,9,0.86); backdrop-filter: blur(10px);
  border-radius: 8px; box-shadow: 0 20px 70px rgba(0,0,0,0.5);
  animation: dayIn 1.1s both;
  pointer-events: none;
}
.day-banner > span { font-size: 36px; }
.day-banner strong { display: block; font-family: var(--display); font-size: 27px; color: var(--amber-2); }
.day-banner p { margin: 1px 0 0; font-size: 11px; color: #b5b49d; }
@keyframes dayIn { 0% { opacity: 0; transform: translate(-50%, -45%) scale(0.97); } 15%, 75% { opacity: 1; transform: translate(-50%, -50%); } 100% { opacity: 0; transform: translate(-50%, -54%); } }

.marker-hud {
  position: absolute; top: 104px; left: 50%; transform: translateX(-50%);
  display: flex; align-items: center; gap: 8px;
  padding: 5px 12px; border-radius: 20px;
  border: 1px solid rgba(224,185,95,0.3);
  background: rgba(11,15,10,0.72); backdrop-filter: blur(7px);
  font-size: 10px; color: #e0dcbf;
}
.marker-hud .mk-icon { font-size: 13px; }
.marker-hud #markerDist { font-family: var(--mono); color: var(--amber); font-size: 9px; }
.downed-overlay { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; background: radial-gradient(circle, rgba(58,8,8,0.28), rgba(0,0,0,0.7)); backdrop-filter: blur(2px) saturate(0.5); z-index: 5; }
.downed-box { text-align: center; }
.downed-icon { font-size: 52px; filter: drop-shadow(0 0 26px rgba(208,95,84,0.4)); }
.downed-box h2 { font-family: var(--display); font-size: 39px; margin: 5px 0 4px; color: #e7c5bd; letter-spacing: -0.02em; }
.downed-box p { margin: 0; font-size: 12px; color: #c39c94; }

.chat-box {
  position: absolute; left: 18px; bottom: 154px; width: min(340px, calc(100vw - 36px));
  display: flex; flex-direction: column; gap: 6px; z-index: 4;
}
.chat-log { max-height: 138px; overflow: auto; display: flex; flex-direction: column; gap: 3px; font-size: 10.5px; text-shadow: 0 1px 3px #000; }
.chat-log div { padding: 2px 7px; border-radius: 3px; background: rgba(8,12,8,0.55); color: #d2d4c1; width: fit-content; max-width: 100%; }
.chat-log .c-name { color: var(--amber); font-weight: 700; }
.chat-log .c-system { color: #999f8c; font-style: italic; }
.chat-toggle { position: absolute; left: 18px; bottom: 125px; width: 32px; height: 32px; border-radius: 50%; border: 1px solid var(--line-strong); background: rgba(10,14,10,0.8); font-size: 14px; }

/* ==========================================================================
   OVERLAYS / MODAIS
   ========================================================================== */
.overlay {
  position: fixed; inset: 0; z-index: 30;
  display: flex; align-items: center; justify-content: center;
  padding: 20px;
  background: rgba(3, 5, 3, 0.62);
  backdrop-filter: blur(7px) saturate(0.85);
  animation: fadeIn 0.18s both;
}
.panel {
  position: relative;
  width: min(760px, calc(100vw - 40px));
  max-height: calc(100vh - 40px);
  display: flex; flex-direction: column;
  border: 1px solid var(--line-strong);
  border-radius: var(--radius);
  background:
    linear-gradient(155deg, rgba(29, 35, 25, 0.985), rgba(11, 14, 10, 0.99)),
    repeating-linear-gradient(90deg, rgba(255,255,255,0.012) 0 1px, transparent 1px 8px);
  box-shadow: var(--shadow), inset 0 1px rgba(255,255,255,0.045);
  animation: panelIn 0.25s cubic-bezier(.18,.78,.3,1) both;
  overflow: hidden;
}
.panel::before { content: ""; position: absolute; inset: 0; pointer-events: none; background: radial-gradient(circle at 92% 0%, rgba(224,185,95,0.07), transparent 38%); }
.panel.wide { width: min(1060px, calc(100vw - 32px)); }
.panel-header { flex: 0 0 auto; }
.panel-header .panel-title { flex: 1; }
.panel-header .panel-title + .btn-close { margin-left: 0; }

/* ---------- Inventário ---------- */
.inv-panel { height: min(760px, calc(100vh - 40px)); }
.inv-weight { font-family: var(--mono); font-size: 11.5px; color: var(--amber); padding: 5px 10px; border: 1px solid rgba(224,185,95,0.24); border-radius: 4px; }
.inv-toolbar { display: flex; flex-wrap: wrap; gap: 5px; padding: 10px 20px; border-bottom: 1px solid var(--line); flex: 0 0 auto; }
.inv-filter { padding: 4px 10px; border-radius: 20px; border: 1px solid var(--line); color: #999f8c; font-size: 10px; transition: all 0.15s; }
.inv-filter:hover { color: #ddd; border-color: rgba(255,255,255,0.24); }
.inv-filter.active { color: #1b190f; background: var(--amber); border-color: var(--amber); font-weight: 700; }
.inv-layout { display: grid; grid-template-columns: minmax(0, 1.45fr) minmax(250px, 0.85fr); min-height: 0; flex: 1; }
.inv-list { padding: 10px; overflow: auto; display: flex; flex-direction: column; gap: 4px; border-right: 1px solid var(--line); }
.inv-row {
  display: grid; grid-template-columns: 36px 1fr auto; align-items: center; gap: 10px;
  padding: 8px 10px; border: 1px solid transparent; border-radius: 6px;
  background: rgba(255,255,255,0.022); cursor: pointer;
  transition: background 0.13s, border-color 0.13s;
}
.inv-row:hover { background: rgba(255,255,255,0.05); }
.inv-row.selected { border-color: rgba(224,185,95,0.5); background: rgba(224,185,95,0.085); }
.inv-row .ir-icon { width: 34px; height: 34px; display: flex; align-items: center; justify-content: center; font-size: 19px; background: rgba(0,0,0,0.24); border-radius: 5px; }
.inv-row .ir-main { min-width: 0; }
.inv-row .ir-name { color: #dddcc9; font-size: 12px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.inv-row .ir-name .equipped { color: var(--amber); font-size: 8px; border: 1px solid rgba(224,185,95,0.4); border-radius: 3px; padding: 0 4px; margin-left: 5px; letter-spacing: 0.05em; }
.inv-row .ir-sub { font-size: 9px; color: #858b78; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.inv-row .ir-qty { font-family: var(--mono); font-size: 11px; color: #c9cbb7; }
.inv-row .ir-bar { grid-column: 2 / 4; height: 2px; background: rgba(255,255,255,0.08); border-radius: 2px; margin-top: 3px; overflow: hidden; }
.inv-row .ir-bar i { display: block; height: 100%; background: var(--green); }
.inv-detail { padding: 22px; overflow: auto; }
.inv-detail .empty-state { color: #737a68; font-size: 11.5px; text-align: center; margin-top: 50px; padding: 0 20px; }
.id-icon { font-size: 38px; margin-bottom: 8px; filter: drop-shadow(0 4px 12px rgba(0,0,0,0.4)); }
.id-name { font-family: var(--display); font-size: 24px; line-height: 1.1; margin: 0 0 2px; color: #ecead8; }
.id-type { font-size: 8.5px; letter-spacing: 0.2em; text-transform: uppercase; color: var(--amber-dim); margin-bottom: 12px; }
.id-desc { color: #a9ad98; font-size: 11.5px; line-height: 1.6; border-top: 1px solid var(--line); padding-top: 12px; margin-bottom: 14px; }
.id-stats { display: grid; grid-template-columns: 1fr auto; gap: 4px 14px; margin-bottom: 17px; font-size: 10.5px; }
.id-stats span { color: #868c79; }
.id-stats strong { color: #d4d5c2; font-weight: 600; text-align: right; }
.id-actions { display: flex; flex-direction: column; gap: 7px; }
.id-actions button { width: 100%; }
.inv-footer { display: flex; justify-content: space-between; gap: 15px; padding: 9px 20px; border-top: 1px solid var(--line); color: #6d7463; font-size: 9.5px; flex: 0 0 auto; }

/* ---------- Construção / fabricação ---------- */
.build-panel { height: min(800px, calc(100vh - 40px)); }
.build-materials { display: flex; flex-wrap: wrap; gap: 5px; margin-right: 8px; justify-content: flex-end; }
.bm-chip { font-size: 9px; border: 1px solid var(--line); border-radius: 4px; padding: 2px 6px; color: #aeb19d; background: rgba(0,0,0,0.2); }
.tab-row { display: flex; align-items: center; gap: 5px; padding: 10px 20px 0; border-bottom: 1px solid var(--line); flex: 0 0 auto; }
.tab { padding: 8px 14px; color: #909684; font-size: 11.5px; border-bottom: 2px solid transparent; margin-bottom: -1px; }
.tab:hover { color: #ddd; }
.tab.active { color: var(--amber-2); border-bottom-color: var(--amber); }
.tab-hint { margin-left: auto; font-size: 9px; color: #6f7664; padding-bottom: 7px; }
.build-grid { padding: 15px 18px 20px; overflow: auto; display: grid; grid-template-columns: repeat(auto-fill, minmax(226px, 1fr)); gap: 9px; align-content: start; flex: 1; }
.build-card {
  position: relative; display: flex; flex-direction: column; gap: 7px;
  text-align: left; padding: 12px 13px; min-height: 140px;
  border: 1px solid var(--line); border-radius: 8px;
  background: linear-gradient(155deg, rgba(255,255,255,0.035), rgba(255,255,255,0.012));
  transition: all 0.15s;
}
.build-card:hover { transform: translateY(-2px); border-color: rgba(224,185,95,0.36); background: rgba(255,255,255,0.05); }
.build-card.unaffordable { opacity: 0.5; }
.build-card.unaffordable:hover { transform: none; }
.bc-head { display: flex; align-items: center; gap: 8px; }
.bc-icon { font-size: 21px; }
.bc-name { font-family: var(--display); font-size: 15px; color: #e6e4d2; }
.bc-desc { font-size: 10px; line-height: 1.45; color: #8f9582; flex: 1; }
.bc-cost { display: flex; flex-wrap: wrap; gap: 4px; }
.bc-cost span { font-size: 8.5px; padding: 1px 5px; border-radius: 3px; background: rgba(0,0,0,0.24); border: 1px solid rgba(255,255,255,0.07); color: #b6b8a5; }
.bc-cost span.missing { color: #e89a8f; border-color: rgba(208,95,84,0.3); background: rgba(208,95,84,0.08); }
.bc-meta { display: flex; justify-content: space-between; gap: 8px; font-size: 8.5px; color: #6f7663; }

/* ---------- Habilidades ---------- */
.skills-panel { height: min(820px, calc(100vh - 40px)); }
.player-level { font-family: var(--mono); font-size: 11px; color: var(--amber); border: 1px solid rgba(224,185,95,0.28); border-radius: 4px; padding: 4px 9px; }
.skills-grid { padding: 18px 20px; display: grid; grid-template-columns: repeat(auto-fill, minmax(240px, 1fr)); gap: 9px; overflow: auto; flex: 1; }
.skill-card { padding: 12px 14px; border: 1px solid var(--line); border-radius: 8px; background: rgba(255,255,255,0.025); }
.skill-head { display: flex; align-items: center; gap: 9px; margin-bottom: 4px; }
.skill-head .si { font-size: 18px; }
.skill-head strong { font-size: 12.5px; color: #dedfcc; flex: 1; }
.skill-level { font-family: var(--mono); font-size: 10px; color: var(--amber); }
.skill-desc { font-size: 9.5px; color: #7f8673; line-height: 1.45; margin-bottom: 8px; min-height: 27px; }
.skill-bar { height: 4px; background: rgba(255,255,255,0.07); border-radius: 4px; overflow: hidden; }
.skill-bar i { display: block; height: 100%; background: linear-gradient(90deg, #7c652e, var(--amber-2)); }
.skill-xp { font-size: 8px; color: #777e6b; margin-top: 3px; text-align: right; font-family: var(--mono); }
.stats-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(110px, 1fr)); gap: 8px; padding: 0 20px 20px; flex: 0 0 auto; }
.stat-card { border: 1px solid var(--line); border-radius: 6px; padding: 9px 11px; background: rgba(0,0,0,0.17); }
.stat-card span { display: block; font-size: 8px; letter-spacing: 0.14em; color: #767d6a; text-transform: uppercase; }
.stat-card strong { display: block; font-family: var(--mono); font-size: 16px; color: #d7d8c4; font-weight: 500; }

/* ---------- Mapa ---------- */
.map-panel { width: min(1120px, calc(100vw - 32px)); height: min(900px, calc(100vh - 32px)); }
.map-meta { font-family: var(--mono); font-size: 10px; color: #a9ad98; }
.map-wrap { flex: 1; min-height: 0; display: flex; align-items: center; justify-content: center; padding: 12px; background: rgba(0,0,0,0.18); overflow: hidden; }
#mapCanvas { max-width: 100%; max-height: 100%; width: auto; height: auto; border-radius: 5px; box-shadow: 0 12px 38px rgba(0,0,0,0.35); }
.map-footer { display: flex; justify-content: space-between; gap: 16px; padding: 8px 18px; border-top: 1px solid var(--line); font-size: 9px; color: #6f7664; }
.legend-you { color: var(--amber-2); }

/* ---------- Saque ---------- */
.loot-panel { width: min(860px, calc(100vw - 36px)); height: min(620px, calc(100vh - 40px)); }
.loot-layout { display: grid; grid-template-columns: 1fr 1fr; min-height: 0; flex: 1; }
.loot-column { display: flex; flex-direction: column; min-height: 0; padding: 12px 14px; }
.loot-column + .loot-column { border-left: 1px solid var(--line); }
.loot-head { display: flex; justify-content: space-between; align-items: center; padding: 0 2px 8px; border-bottom: 1px solid var(--line); margin-bottom: 8px; font-size: 10px; letter-spacing: 0.12em; text-transform: uppercase; color: #a9ad98; }
.loot-head em { font-style: normal; font-family: var(--mono); letter-spacing: 0; color: var(--amber); text-transform: none; }
.loot-items { overflow: auto; display: flex; flex-direction: column; gap: 4px; flex: 1; }
.loot-row { display: grid; grid-template-columns: 31px 1fr auto; gap: 8px; align-items: center; padding: 7px 8px; border: 1px solid transparent; border-radius: 5px; background: rgba(255,255,255,0.025); cursor: pointer; text-align: left; transition: all 0.13s; }
.loot-row:hover { background: rgba(224,185,95,0.09); border-color: rgba(224,185,95,0.3); }
.loot-row .li-icon { font-size: 17px; text-align: center; }
.loot-row .li-name { font-size: 11px; color: #d4d5c2; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.loot-row .li-sub { display: block; font-size: 8.5px; color: #7e8572; }
.loot-row .li-qty { font-family: var(--mono); font-size: 10px; color: #b8baa7; }
